import Box from '@mui/material/Box';
import Button, {
  type ButtonProps,
  type ButtonTypeMap,
} from '@mui/material/Button';
import type { ExtendButtonBase } from '@mui/material/ButtonBase';
import { ButtonGroupContext } from '@mui/material/ButtonGroup';
import CircularProgress from '@mui/material/CircularProgress';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, useContext, useId, type ElementType } from 'react';
import { buttonStyles, type SvButtonState } from './sv-button.styles.ts';

export type SvButtonAppearance =
  | 'default'
  | 'secondary'
  | 'success'
  | 'tooltip'
  | 'server'
  | 'serverSecondary'
  | 'nerf'
  | 'nerfSecondary';

interface SvButtonOwnProps {
  /** StreamVi appearance. Success defaults to the success palette; a resolved color overrides it. Variant and size retain their MUI meanings. */
  appearance?: SvButtonAppearance | undefined;
}

export type SvButtonProps<C extends ElementType = 'button'> = ButtonProps<
  C,
  SvButtonOwnProps
>;

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvButton: SvButtonProps;
  }
  interface Components {
    SvButton?:
      { defaultProps?: Partial<SvButtonProps> | undefined } | undefined;
  }
}

export const SvButton = forwardRef<HTMLButtonElement, SvButtonProps>(
  function SvButton(inProps, ref) {
    const group = useContext(ButtonGroupContext);
    const muiDefaults = useDefaultProps<SvButtonProps>({
      props: {},
      name: 'MuiButton',
    });
    const svDefaults = useDefaultProps<SvButtonProps>({
      props: {},
      name: 'SvButton',
    });
    // Undefined means absent, as in MUI. Button itself forwards the group classes.
    const groupedProps = { ...inProps };
    for (const key of [
      'color',
      'disabled',
      'disableElevation',
      'disableFocusRipple',
      'disableRipple',
      'fullWidth',
      'size',
      'variant',
    ] as const) {
      if (groupedProps[key] === undefined && group[key] !== undefined) {
        Object.assign(groupedProps, { [key]: group[key] });
      }
    }
    const svProps = useDefaultProps({ props: groupedProps, name: 'SvButton' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiButton' });
    const {
      appearance = 'default',
      variant = 'contained',
      color = appearance === 'success' ? 'success' : 'primary',
      size = 'medium',
      disableElevation = true,
      loading = null,
      loadingIndicator,
      loadingPosition,
      children,
      className,
      id: suppliedId,
      ...props
    } = resolved;
    const generatedId = useId();
    const id = suppliedId ?? generatedId;
    const hasColor = resolved.color !== undefined;
    const customLoading =
      loadingIndicator !== undefined || loadingPosition !== undefined;
    const loadingMode = customLoading
      ? 'mui'
      : variant === 'text'
        ? 'text'
        : variant === 'contained' &&
            ((appearance === 'default' && color === 'primary') ||
              (appearance === 'secondary' && !hasColor))
          ? 'stripes'
          : 'mui';
    const ownerState: SvButtonState = {
      ...resolved,
      appearance,
      variant,
      color,
      size,
      hasColor,
      loadingMode,
      loading,
      loadingPosition: loadingPosition ?? 'center',
    };
    const indicator =
      loadingMode === 'stripes' ? (
        <Box component="span" role="progressbar" aria-labelledby={id} />
      ) : loadingMode === 'mui' ? (
        loadingIndicator
      ) : (
        <CircularProgress color="inherit" size={16} aria-labelledby={id} />
      );
    return (
      <Button
        {...props}
        id={id}
        ref={ref}
        className={clsx(
          'SvButton-root',
          `SvButton-appearance-${appearance}`,
          className
        )}
        variant={variant}
        color={color}
        size={size}
        disableElevation={disableElevation}
        loading={loading}
        loadingIndicator={indicator}
        loadingPosition={loadingPosition}
        aria-busy={loading ? true : props['aria-busy']}
        sx={mergeSx(
          (theme) => buttonStyles(theme, ownerState),
          muiDefaults.sx,
          svDefaults.sx,
          inProps.sx
        )}
      >
        <span className="SvButton-label">{children}</span>
      </Button>
    );
  }
) as ExtendButtonBase<ButtonTypeMap<SvButtonOwnProps>>;
